// SymForce runner for the localization benchmark -- the generated-code path:
// the four residuals are defined symbolically in ../symforce_gen.py,
// code-generated by SymForce into flattened C++ linearization functions
// (symforce_gen/*_factor.h), and executed by SymForce's own C++ sym::Optimizer
// (LM). Templated over double/float.
//
// Reads the scene exported by the Rust harness (identical problem; same file
// the Ceres runner reads). Pose blocks are plain 6-vectors [x,y,z,roll,pitch,
// yaw] optimized as V6 (additive retraction, matching arael's
// SimpleEulerAngleParam). Landmarks are FIXED -- stored as constant values,
// never optimized, so the bearing factor linearizes only w.r.t. the pose. The
// euler convention and odometry euler extraction are baked into the generated
// residuals, so every residual equals scene::reference_cost.
//
//   symforce_loc <scene.txt> <f64|f32> <solution_out>
// JSON {solve_ms, first_iter_ms, iterations, accepted, initial_cost,
// peak_rss_kb, cpus_allowed} on stdout; solution_out carries one pose per line
// (6 values). Landmarks are fixed and not written.
// SYMFORCE_LAMBDA0 overrides the initial damping (default 1e-10).

#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <string>
#include <vector>

#include <Eigen/Dense>
#include <symforce/opt/factor.h>
#include <symforce/opt/key.h>
#include <symforce/opt/optimizer.h>

#include "symforce_gen/bearing_factor.h"
#include "symforce_gen/drift_factor.h"
#include "symforce_gen/odo_factor.h"
#include "symforce_gen/tilt_factor.h"

struct Globals {
    double drift_pos_isigma, drift_ea_isigma, tilt_isigma, frine_isigma_scale;
};

struct Scene {
    int n_poses, n_landmarks, n_frines, n_odo;
    Globals g;
    std::vector<double> pose_init;    // 6 per pose
    std::vector<double> tilt;         // 2 per pose
    std::vector<double> lm_pos;       // 3 per landmark (FIXED)
    std::vector<int> f_pose, f_lm;
    std::vector<double> f_mf2r, f_camera_pos, f_isigma;
    std::vector<int> o_prev, o_cur;
    std::vector<double> o_dpos, o_dea, o_pcr, o_pci, o_ecr, o_eci;
};

static void rd(std::ifstream& f, double* d, int n) { for (int i = 0; i < n; i++) f >> d[i]; }

static Scene load(const char* path) {
    std::ifstream f(path);
    Scene s;
    f >> s.n_poses >> s.n_landmarks >> s.n_frines >> s.n_odo;
    f >> s.g.drift_pos_isigma >> s.g.drift_ea_isigma
      >> s.g.tilt_isigma >> s.g.frine_isigma_scale;
    s.pose_init.resize(6 * s.n_poses); s.tilt.resize(2 * s.n_poses);
    for (int i = 0; i < s.n_poses; i++) {
        rd(f, &s.pose_init[6 * i], 6);
        rd(f, &s.tilt[2 * i], 2);
    }
    s.lm_pos.resize(3 * s.n_landmarks);
    for (int i = 0; i < s.n_landmarks; i++) rd(f, &s.lm_pos[3 * i], 3);
    s.f_pose.resize(s.n_frines); s.f_lm.resize(s.n_frines);
    s.f_mf2r.resize(9 * s.n_frines); s.f_camera_pos.resize(3 * s.n_frines);
    s.f_isigma.resize(2 * s.n_frines);
    for (int i = 0; i < s.n_frines; i++) {
        f >> s.f_pose[i] >> s.f_lm[i];
        rd(f, &s.f_mf2r[9 * i], 9);
        rd(f, &s.f_camera_pos[3 * i], 3);
        rd(f, &s.f_isigma[2 * i], 2);
    }
    s.o_prev.resize(s.n_odo); s.o_cur.resize(s.n_odo);
    s.o_dpos.resize(3 * s.n_odo); s.o_dea.resize(3 * s.n_odo);
    s.o_pcr.resize(9 * s.n_odo); s.o_pci.resize(3 * s.n_odo);
    s.o_ecr.resize(9 * s.n_odo); s.o_eci.resize(3 * s.n_odo);
    for (int i = 0; i < s.n_odo; i++) {
        f >> s.o_prev[i] >> s.o_cur[i];
        rd(f, &s.o_dpos[3 * i], 3);
        rd(f, &s.o_dea[3 * i], 3);
        rd(f, &s.o_pcr[9 * i], 9);
        rd(f, &s.o_pci[3 * i], 3);
        rd(f, &s.o_ecr[9 * i], 9);
        rd(f, &s.o_eci[3 * i], 3);
    }
    return s;
}

template <typename Scalar>
static Eigen::Matrix<Scalar, 3, 3> m33(const double* d) {
    Eigen::Matrix<Scalar, 3, 3> m;
    for (int r = 0; r < 3; r++)
        for (int c = 0; c < 3; c++) m(r, c) = Scalar(d[3 * r + c]);
    return m;
}
template <typename Scalar, int N>
static Eigen::Matrix<Scalar, N, 1> vecN(const double* d) {
    Eigen::Matrix<Scalar, N, 1> v;
    for (int i = 0; i < N; i++) v[i] = Scalar(d[i]);
    return v;
}

// Canonical cost of the initial estimate, evaluated by the GENERATED residual
// functions in double -- the harness cross-checks this against the reference.
static double initial_cost(const Scene& s) {
    double cost = 0.0;
    Eigen::Matrix<double, 6, 1> r6;
    Eigen::Matrix<double, 2, 1> r2;
    for (int i = 0; i < s.n_poses; i++) {
        auto pose = vecN<double, 6>(&s.pose_init[6 * i]);
        sym::DriftFactor<double>(pose, vecN<double, 6>(&s.pose_init[6 * i]),
                                 s.g.drift_pos_isigma, s.g.drift_ea_isigma, &r6);
        cost += r6.squaredNorm();
        sym::TiltFactor<double>(pose, vecN<double, 2>(&s.tilt[2 * i]), s.g.tilt_isigma, &r2);
        cost += r2.squaredNorm();
    }
    for (int k = 0; k < s.n_frines; k++) {
        sym::BearingFactor<double>(vecN<double, 6>(&s.pose_init[6 * s.f_pose[k]]),
                                   vecN<double, 3>(&s.lm_pos[3 * s.f_lm[k]]),
                                   m33<double>(&s.f_mf2r[9 * k]),
                                   vecN<double, 3>(&s.f_camera_pos[3 * k]),
                                   vecN<double, 2>(&s.f_isigma[2 * k]),
                                   s.g.frine_isigma_scale, &r2);
        cost += r2.squaredNorm();
    }
    for (int o = 0; o < s.n_odo; o++) {
        sym::OdoFactor<double>(vecN<double, 6>(&s.pose_init[6 * s.o_prev[o]]),
                               vecN<double, 6>(&s.pose_init[6 * s.o_cur[o]]),
                               vecN<double, 3>(&s.o_dpos[3 * o]), vecN<double, 3>(&s.o_dea[3 * o]),
                               m33<double>(&s.o_pcr[9 * o]), vecN<double, 3>(&s.o_pci[3 * o]),
                               m33<double>(&s.o_ecr[9 * o]), vecN<double, 3>(&s.o_eci[3 * o]), &r6);
        cost += r6.squaredNorm();
    }
    return cost;
}

struct RunResult { double ms; int accepted, total; };

template <typename Scalar>
static RunResult solve(const Scene& s, int max_iters, std::vector<double>* pose_out) {
    using V6 = Eigen::Matrix<Scalar, 6, 1>;

    sym::Values<Scalar> v;
    // Optimized variables: poses only.
    for (int i = 0; i < s.n_poses; i++) v.Set(sym::Key('P', i), vecN<Scalar, 6>(&s.pose_init[6 * i]));
    // Fixed landmarks -- constant values, never in an optimized-key list.
    for (int j = 0; j < s.n_landmarks; j++) v.Set(sym::Key('l', j), vecN<Scalar, 3>(&s.lm_pos[3 * j]));
    // Shared scalar constants.
    v.Set(sym::Key('Y'), Scalar(s.g.drift_pos_isigma));
    v.Set(sym::Key('Z'), Scalar(s.g.drift_ea_isigma));
    v.Set(sym::Key('U'), Scalar(s.g.tilt_isigma));
    v.Set(sym::Key('S'), Scalar(s.g.frine_isigma_scale));
    // Per-factor constants.
    for (int i = 0; i < s.n_poses; i++) {
        v.Set(sym::Key('p', i), vecN<Scalar, 6>(&s.pose_init[6 * i]));
        v.Set(sym::Key('t', i), vecN<Scalar, 2>(&s.tilt[2 * i]));
    }
    for (int k = 0; k < s.n_frines; k++) {
        v.Set(sym::Key('m', k), m33<Scalar>(&s.f_mf2r[9 * k]));
        v.Set(sym::Key('n', k), vecN<Scalar, 3>(&s.f_camera_pos[3 * k]));
        v.Set(sym::Key('i', k), vecN<Scalar, 2>(&s.f_isigma[2 * k]));
    }
    for (int o = 0; o < s.n_odo; o++) {
        v.Set(sym::Key('a', o), vecN<Scalar, 3>(&s.o_dpos[3 * o]));
        v.Set(sym::Key('b', o), vecN<Scalar, 3>(&s.o_dea[3 * o]));
        v.Set(sym::Key('C', o), m33<Scalar>(&s.o_pcr[9 * o]));
        v.Set(sym::Key('d', o), vecN<Scalar, 3>(&s.o_pci[3 * o]));
        v.Set(sym::Key('D', o), m33<Scalar>(&s.o_ecr[9 * o]));
        v.Set(sym::Key('e', o), vecN<Scalar, 3>(&s.o_eci[3 * o]));
    }

    std::vector<sym::Factor<Scalar>> factors;
    factors.reserve(2 * s.n_poses + s.n_frines + s.n_odo);
    for (int i = 0; i < s.n_poses; i++) {
        factors.push_back(sym::Factor<Scalar>::Hessian(
            sym::DriftFactor<Scalar>,
            {sym::Key('P', i), sym::Key('p', i), sym::Key('Y'), sym::Key('Z')},
            {sym::Key('P', i)}));
        factors.push_back(sym::Factor<Scalar>::Hessian(
            sym::TiltFactor<Scalar>,
            {sym::Key('P', i), sym::Key('t', i), sym::Key('U')},
            {sym::Key('P', i)}));
    }
    for (int k = 0; k < s.n_frines; k++) {
        factors.push_back(sym::Factor<Scalar>::Hessian(
            sym::BearingFactor<Scalar>,
            {sym::Key('P', s.f_pose[k]), sym::Key('l', s.f_lm[k]), sym::Key('m', k),
             sym::Key('n', k), sym::Key('i', k), sym::Key('S')},
            {sym::Key('P', s.f_pose[k])}));
    }
    for (int o = 0; o < s.n_odo; o++) {
        factors.push_back(sym::Factor<Scalar>::Hessian(
            sym::OdoFactor<Scalar>,
            {sym::Key('P', s.o_prev[o]), sym::Key('P', s.o_cur[o]), sym::Key('a', o),
             sym::Key('b', o), sym::Key('C', o), sym::Key('d', o), sym::Key('D', o), sym::Key('e', o)},
            {sym::Key('P', s.o_prev[o]), sym::Key('P', s.o_cur[o])}));
    }

    auto params = sym::DefaultOptimizerParams();
    params.iterations = max_iters;
    params.early_exit_min_reduction = 1e-5;  // shared termination class
    params.initial_lambda = 1e-10;
    if (const char* l = getenv("SYMFORCE_LAMBDA0")) params.initial_lambda = atof(l);

    sym::Optimizer<Scalar> optimizer(params, std::move(factors));
    auto t0 = std::chrono::steady_clock::now();
    auto stats = optimizer.Optimize(v);
    double ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();

    int accepted = 0;
    for (const auto& it : stats.iterations) if (it.update_accepted) accepted++;
    if (pose_out) {
        pose_out->resize(6 * s.n_poses);
        for (int i = 0; i < s.n_poses; i++) {
            V6 p = v.template At<V6>(sym::Key('P', i));
            for (int k = 0; k < 6; k++) (*pose_out)[6 * i + k] = double(p[k]);
        }
    }
    return RunResult{ms, accepted, (int)stats.iterations.size()};
}

static long peak_rss_kb() {
    std::ifstream st("/proc/self/status");
    std::string l;
    while (std::getline(st, l))
        if (l.rfind("VmHWM:", 0) == 0) return atol(l.c_str() + 6);
    return 0;
}

template <typename Scalar>
static void run(const Scene& s, const char* solution_out) {
    int max_iters = 200;
    if (const char* m = getenv("SYMFORCE_MAXITER")) max_iters = atoi(m);
    RunResult first = solve<Scalar>(s, 1, nullptr);
    std::vector<double> poses;
    RunResult full = solve<Scalar>(s, max_iters, &poses);

    std::ofstream out(solution_out);
    out.precision(17);
    for (int i = 0; i < s.n_poses; i++)
        for (int k = 0; k < 6; k++) out << poses[6 * i + k] << (k == 5 ? "\n" : " ");

    std::string cpus = "?";
    std::ifstream st("/proc/self/status");
    std::string l;
    while (std::getline(st, l))
        if (l.rfind("Cpus_allowed_list:", 0) == 0)
            cpus = l.substr(l.find_last_of(" \t") + 1);

    printf("{\"solve_ms\": %.3f, \"first_iter_ms\": %.3f, \"iterations\": %d, "
           "\"accepted\": %d, \"initial_cost\": %.6f, \"peak_rss_kb\": %ld, \"cpus_allowed\": \"%s\"}\n",
           full.ms, first.ms, full.total, full.accepted, initial_cost(s), peak_rss_kb(), cpus.c_str());
}

int main(int argc, char** argv) {
    setenv("SYMFORCE_TIC_TOC_QUIET", "1", 0);
    if (argc < 4) { fprintf(stderr, "usage: %s <scene.txt> <f64|f32> <solution_out>\n", argv[0]); return 1; }
    Scene s = load(argv[1]);
    if (std::string(argv[2]) == "f32") run<float>(s, argv[3]);
    else run<double>(s, argv[3]);
    return 0;
}
